const visual = {
  prepare: function (input) {
    var vals = [0, 20, 40, 60, 80, 100];
    return vals.map(function (v) { return { kind: 'text', payload: String(v) }; });
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var left = Math.max(36, Math.min(64, w * 0.12));
    var right = left;
    var x0 = left;
    var x1 = w - right;
    if (x1 <= x0 + 20) {
      x0 = 20;
      x1 = Math.max(60, w - 20);
    }
    var axisY = Math.round(h * 0.58);
    var axis = visualSdk.axis({
      x0: x0,
      y0: axisY,
      x1: x1,
      y1: axisY,
      ticks: 6,
      tickLength: 8
    });
    var children = [
      { type: 'path', pathId: 'axis', fill: '#26354a', stroke: { width: 2, cap: 'round' } }
    ];
    for (var i = 0; i < 6; i++) {
      var x = x0 + (x1 - x0) * i / 5;
      var hAlign = i === 0 ? 'left' : (i === 5 ? 'right' : 'center');
      children.push({
        type: 'label',
        contentId: metrics[i].contentId,
        anchor: { x: x, y: axisY + 14 },
        hAlign: hAlign,
        vAlign: 'top',
        color: '#26354a'
      });
    }
    return {
      schemaVersion: 1,
      sceneId: 'axis-0-100',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [{ id: 'axis', commands: axis }],
      root: { type: 'group', children: children }
    };
  }
};
